name: Notify Dev Channel

on:
  push:
    branches: [master]
    paths:
      - 'src/**'

permissions:
  contents: read
  issues: write
  pull-requests: write

jobs:
  notify:
    runs-on: ubuntu-latest
    steps:
      - name: Extract PR number from commit message
        id: extract_pr
        run: |
          COMMIT_MESSAGE="${{ github.event.head_commit.message }}"
          PR_NUMBER=$(echo "$COMMIT_MESSAGE" | grep -oE '#[0-9]+' | head -1 | sed 's/#//')
          echo "pr_number=$PR_NUMBER" >> $GITHUB_OUTPUT
          echo "Commit message: $COMMIT_MESSAGE"
          echo "Extracted PR number: $PR_NUMBER"

      - name: Get PR details
        if: steps.extract_pr.outputs.pr_number != ''
        id: get_pr
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ steps.extract_pr.outputs.pr_number }};
            try {
              const { data: pr } = await github.rest.pulls.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: parseInt(prNumber)
              });

              // Extract issue numbers from PR body
              const issueRegex = /(?:Closes|Fixes|Resolves)\s+(?:#\d+\s*)+/gi;
              const matches = pr.body.match(issueRegex);
              let issueNumbers = [];
              if (matches) {
                issueNumbers = matches.flatMap(match => 
                  match.match(/#\d+/g)?.map(m => m.slice(1)) || []
                );
              }

              // Remove duplicates
              issueNumbers = [...new Set(issueNumbers)];

              core.setOutput('pr_title', pr.title);
              core.setOutput('pr_body', pr.body);
              core.setOutput('pr_url', pr.html_url);
              core.setOutput('issue_numbers', issueNumbers.join(','));
              core.setOutput('pr_number', prNumber);
            } catch (error) {
              console.log("Failed to get PR details:", error.message);
              core.setOutput('pr_title', '');
              core.setOutput('pr_body', '');
              core.setOutput('pr_url', '');
              core.setOutput('issue_numbers', '');
              core.setOutput('pr_number', '');
            }

      - name: Post comment to PR
        if: steps.get_pr.outputs.pr_number != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const prNumber = ${{ steps.get_pr.outputs.pr_number }};
            const prTitle = ${{ steps.get_pr.outputs.pr_title }};
            const prUrl = ${{ steps.get_pr.outputs.pr_url }};

            const comment = """
## 🧪 Your changes are now in the dev channel!

Your PR has been merged to master and is available for testing in the **dev channel**.

**Test your changes before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: `uvx ha-mcp-dev`
            """;

            try {
              await github.rest.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: parseInt(prNumber),
                body: comment
              });
              console.log(`Successfully commented on PR #${prNumber}`);
            } catch (error) {
              console.log("Failed to post comment to PR:", error.message);
            }

      - name: Post comment to linked issues
        if: steps.get_pr.outputs.issue_numbers != ''
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const issueNumbers = ${{ steps.get_pr.outputs.issue_numbers }}.split(',');
            const prNumber = ${{ steps.get_pr.outputs.pr_number }};
            const prTitle = ${{ steps.get_pr.outputs.pr_title }};
            const prUrl = ${{ steps.get_pr.outputs.pr_url }};

            const comment = """
## ✅ This issue has been addressed in the dev channel!

A fix for this issue has been merged to master (PR #${prNumber}) and is available for testing...

**Test before the Tuesday release:**
📖 **[Dev Channel Documentation](https://github.com/homeassistant-ai/ha-mcp/blob/master/docs/dev-channel.md)**

Quick start: `uvx ha-mcp-dev`
            """;

            for (const issueNumber of issueNumbers) {
              try {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: parseInt(issueNumber.trim()),
                  body: comment
                });
                console.log(`Successfully commented on issue #${issueNumber.trim()}`);
              } catch (error) {
                console.log(`Failed to post comment to issue #${issueNumber.trim()}:`, error.message);
              }
            }
